#!/usr/bin/env python3
"""Render a private, self-contained evidence report from a supplied probe bundle."""
import argparse
import base64
import html
import mimetypes
import json
from pathlib import Path
from checklist import load_checklist, render_checklist

parser = argparse.ArgumentParser()
parser.add_argument('--evidence', type=Path, required=True)
parser.add_argument('--output', type=Path, required=True)
args = parser.parse_args()
checklist_data = load_checklist()

def image(name):
    mime = mimetypes.guess_type(name)[0] or 'image/png'
    return 'data:' + mime + ';base64,' + base64.b64encode((args.evidence / name).read_bytes()).decode()

def figure(name, caption):
    return f'<figure><img src="{image(name)}" alt="{html.escape(caption)}"><figcaption>{html.escape(caption)}</figcaption></figure>'

strategy = Path(__file__).with_name('STRATEGY.md').read_text()
